"""Compare generated bytes before/after regeneration, including without a Git repository."""
import hashlib
import subprocess
from pathlib import Path
root = Path(__file__).resolve().parents[1]
locations = ["app/internal/database", "app/internal/httpapi/contract", "web/src/api.gen.ts", "worker/snitch_worker/api"]
def snapshot():
    result = {}
    for location in locations:
        p = root / location
        files = [p] if p.is_file() else p.rglob("*")
        for file in files:
            if file.is_file() and "__pycache__" not in file.parts:
                result[str(file.relative_to(root))] = hashlib.sha256(file.read_bytes()).hexdigest()
    return result
before = snapshot()
subprocess.run(["bash", "scripts/generate.sh"], cwd=root, check=True)
after = snapshot()
assert before == after, "Generated files differ: run bash scripts/generate.sh and commit all outputs"
print("Generated files are reproducible")
